-- --- assert ------------------------------------------------------------------
do $$
declare t text;
begin
  -- THE POINT, asked of the stored rows rather than of the rule list: nothing a
  -- reader can see still mentions the book, the edition or an editor by name.
  -- A count of rules applied would not answer this -- it would only say the
  -- rules ran, not that they were the whole set.
  select string_agg(distinct left(instruction_en, 60), ' | ') into t from public.pooja_steps
   where instruction_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'pooja_steps.instruction_en still cites the source: %', t; end if;
  select string_agg(distinct left(meaning_en, 60), ' | ') into t from public.pooja_steps
   where meaning_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'pooja_steps.meaning_en still cites the source: %', t; end if;
  select string_agg(distinct left(philosophy_en, 60), ' | ') into t from public.pooja_steps
   where philosophy_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'pooja_steps.philosophy_en still cites the source: %', t; end if;
  select string_agg(distinct left(variant_note_en, 60), ' | ') into t from public.pooja_steps
   where variant_note_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'pooja_steps.variant_note_en still cites the source: %', t; end if;
  select string_agg(distinct left(why_en, 60), ' | ') into t from public.poojas
   where why_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'poojas.why_en still cites the source: %', t; end if;
  select string_agg(distinct left(description_en, 60), ' | ') into t from public.poojas
   where description_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'poojas.description_en still cites the source: %', t; end if;
  select string_agg(distinct left(eligibility, 60), ' | ') into t from public.poojas
   where eligibility ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'poojas.eligibility still cites the source: %', t; end if;
  select string_agg(distinct left(recipe_note, 60), ' | ') into t from public.naivedyam_items
   where recipe_note ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'naivedyam_items.recipe_note still cites the source: %', t; end if;
  select string_agg(distinct left(reason_en, 60), ' | ') into t from public.naivedyam_items
   where reason_en ~* '\m(the book|this book|the edition|this edition|Bhavan|the author|the manual)\M';
  if t is not null then raise exception 'naivedyam_items.reason_en still cites the source: %', t; end if;

  -- No sentence lost its spacing to a deletion.
  select string_agg(distinct left(philosophy_en, 60), ' | ') into t from public.pooja_steps
   where philosophy_en like '%  %' or philosophy_en like ' .%';
  if t is not null then raise exception 'double spacing left behind: %', t; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
